+ items=append(items,sample{"heldout_topics",[][]byte{topics.Bytes()}})
+ var short [][]byte
+ for n:=0;n<128;n++ {short=append(short,[]byte(fmt.Sprintf("{\"seq\":%d,\"route\":\"/dat/thread%d\",\"nonce\":\"%016x\",\"body\":\"%s\"}",n,n%11,rng.Uint64(),phrases[n%len(phrases)])))}
+ items=append(items,sample{"heldout_short_records",short})
+ var mixed []byte
+ for _,kind:=range []string{"entropy","text","mixed"} {mixed=append(mixed,testutil.DATFixture(kind)[:65536]...)}
+ items=append(items,sample{"heldout_distribution_change",[][]byte{mixed}})
+ return items
+}

