+// normalizationGain は1状態追加したときの情報量改善を固定小数点24bitで求める。
+var normalizationGain = func() [513]uint32 {
+ var table [513]uint32
+ for n:=1;n<len(table);n++ {
+  ratio:=(uint64(n+1)<<31)/uint64(n)
+  whole:=bits.Len64(ratio)-32
+  value:=ratio>>uint(whole)
+  var fraction uint32
+  for range 24 {value=value*value>>31;fraction<<=1;if value>=1<<32 {value>>=1;fraction++}}
+  table[n]=uint32(whole)<<24|fraction
+ }
+ return table
+}()

